51: const hero=`<section class="hero"><div class="hero-copy"><div class="eyebrow">A family enterprise · ${fmtYear()}</div><h1>Build beyond<br>your own lifetime.</h1><p>Grow enduring businesses, steward capital wisely, and prepare the next generation to carry your name forward.</p><div class="hero-meta"><span><i class="dot"></i>Generation ${Math.min(5,Math.floor((state.year-2026)/4)+1)}</span><span>◷ &nbsp;${Math.max(0,20-(state.year-2026))} YEARS LEFT</span></div></div></section>`;
52: const overview=`<div class="overview"><div class="left-col"><section class="card wealth-card"><div class="section-head"><div class="section-title">Family wealth</div><div class="mono">TOTAL ESTATE</div></div><div class="wealth-total"><strong>${compact(wealthNum)}</strong><span class="change">↗ ${state.history.length?((wealthNum/state.history[0].wealth-1)*100).toFixed(1):'0.0'}%</span></div><div class="chart-wrap">${svgChart()}</div><div class="chart-labels"><span>FOUNDING YEAR</span><span>NOW · ${state.year}</span></div><div class="stats"><div class="stat"><label>Liquid capital</label><b>${compact(state.cash)}</b><small>Available to deploy</small></div><div class="stat"><label>Annual income</label><b>${compact(earnings)}</b><small>From productive assets</small></div><div class="stat"><label>Holdings</label><b>${state.assets.length+ (state.trust>0?1:0)}</b><small>Across ${new Set(state.assets.map(a=>a.kind)).size} sectors</small></div></div></section></div><div class="right-col"><section class="card score-card"><div class="section-head"><div class="section-title">Legacy index</div><div class="mono">OUT OF 100</div></div><div class="score-number">${score}<span style="font:12px 'DM Sans';color:#7b887b"> / 100</span></div><div class="score-sub">${score<35?'A foundation taking shape':score<65?'A respected family institution':score<85?'A lasting dynasty':'An extraordinary legacy'}</div><div class="progress"><i style="width:${score}%"></i></div><div class="score-foot"><span>BUILDING A LEGACY</span><span>${score>=100?'COMPLETE':'GOAL 100'}</span></div></section><section class="card yield-card"><div class="section-head"><div class="section-title">Capital mix</div><div class="mono">PORTFOLIO</div></div><div class="yield-main"><div class="yield-value">${compact(state.assets.reduce((n,a)=>n+a.value,0)+state.trust)}</div><div class="yield-note">${state.assets.length?state.assets.length+' ACTIVE HOLDINGS':'READY TO INVEST'}</div></div><div class="yield-bar"><span></span><span></s... (line truncated to 2000 chars)
53: const moveSection=`<div class="section-row"><div><h2>Make your move</h2><p>One defining decision each year. Choose with care.</p></div><span class="move-count">${state.ended?'LEGACY COMPLETE':canAct?'1 MOVE AVAILABLE':'MOVE MADE'}</span></div><div class="moves">${moveCard('deal','⌂','Acquire an enterprise','Buy a durable business or long-term holding.','', 'EXPLORE DEALS',!canAct)}${moveCard('trust','◈','Create a family trust','Set aside capital for continuity and stewardship.',money(250000),'SECURE THE FUTURE',!canAct||state.cash<250000)}${moveCard('academy','✦','Educate the next generation','Invest in a capable, principled family council.',money(60000),'INVEST IN PEOPLE',!canAct||state.cash<60000)}${moveCard('give','♡','Give with intention','Support a lasting community institution.',money(40000),'BUILD GOODWILL',!canAct||state.cash<40000)}${moveCard('council','♧','Form a family council','Strengthen governance and improve your reputation.',money(90000),'SET A COMMON PURPOSE',!canAct||state.cash<90000)}${moveCard('reserve','⌁','Protect the reserve','Build resilience; add a modest guaranteed return.',money(150000),'LOW-RISK 4.5% YIELD',!canAct||state.cash<150000)}${moveCard('hold','—','Hold steady','Skip investing this year and advance with no upfront cost.','$0','NO-COST ADVANCE',!canAct)}</div>`;
54: let bottom=`<div class="bottom-grid"><section class="card event-card"><div class="event-icon">✧</div><div><div class="event-tag">IN THIS SEASON</div><div class="event-title">${event.title}</div><p class="event-body">${event.body}</p></div></section><section class="card action-card"><div><div class="action-title">${state.ended?'Your story is written':`Year ${state.year} decision`}</div><div class="action-hint">${state.ended?'Start again to build a new legacy.':canAct?'Choose a move, then close the books.':'Your move is set. Ready to advance?'}</div></div><button class="advance" onclick="advanceYear()" ${(state.actions<1&&!state.ended)?'disabled':''}>${state.ended?'NEW LEGACY':'CLOSE THE YEAR →'}</button></section></div>`;
55: let ending=state.ended?`<section class="ending"><div class="eyebrow">THE FAMILY RECORD · ${state.year}</div><h2>${score>=70?'A legacy that endures.':score>=40?'A foundation for generations.':'Every great story begins somewhere.'}</h2><p>Your family stewarded ${compact(wealthNum)} in wealth, built ${state.assets.length} lasting enterprise${state.assets.length===1?'':'s'}, and finished with a Legacy Index of ${score}. ${state.education?`You invested ${money(state.education)} in future leaders. `:''}${state.philanthropy?`Your giving reached ${money(state.philanthropy)}.`:''}</p></section>`:'';
