60: function portfolioView(){let total=state.assets.reduce((n,a)=>n+a.value,0);return `<div class="section-row" style="margin-top:5px"><div><h2>Family portfolio</h2><p>Capital at work, built one generation at a time.</p></div><span class="move-count">${state.assets.length} HOLDINGS</span></div><section class="card wealth-card"><div class="section-head"><div class="section-title">Productive assets</div><div class="mono">${compact(total)} TOTAL VALUE</div></div>${state.assets.length?`<div class="portfolio-list">${state.assets.map((a,i)=>`<div class="asset-row"><strong>${a.name}<br><span style="font:9px 'DM Sans';color:#88938a">${a.kind} · ${a.risk} risk</span></strong><span>${compact(a.value)}<br>value</span><span>${compact(a.value*a.yield)}<br>annual income</span></div>`).join('')}</div>`:`<div class="empty">Your family’s first enterprise is waiting to be acquired.<br>Choose “Explore deals” on the home screen to begin.</div>`}<div class="asset-row" style="border-bottom:1px solid var(--line);margin-top:4px"><strong>Family trust</strong><span>${compact(state.trust)}<br>protected</span><span>${compact(state.trust*.045)}<br>annual income</span></div></section><section class="card wealth-card" style="margin-top:14px"><div class="section-head"><div class="section-title">Stewardship & people</div><div class="mono">NON-FINANCIAL CAPITAL</div></div><div class="stats"><div class="stat"><label>Reputation</label><b>${state.reputation} / 100</b><small>Community standing</small></div><div class="stat"><label>Education</label><b>${compact(state.education)}</b><small>Next-gen investment</small></div><div class="stat"><label>Philanthropy</label><b>${compact(state.philanthropy)}</b><small>Giving to date</small></div></div></section><div class="bottom-grid"><section class="card event-card"><div class="event-icon">✧</div><div><div class="event-tag">A PRINCIPLE TO REMEMBER</div><div class="event-title">Wealth is a responsibility.</div><p class="event-body">Strong family enterprises combine p... (line truncated to 2000 chars)
