64: if(id==='deal'){showDeals();return}
65: if(id==='hold'){state.actions=1;state.logs.push({year:state.year,title:'Held steady',body:'Chose not to make a new investment this year; existing holdings and annual operations continue.'});save();selected=null;notify('No-cost move recorded. You can close the year.');render();return}
66: const options={trust:{title:'Establish a family trust',amount:250000,ok:s=>{s.trust+=250000;s.reputation=Math.min(100,s.reputation+2);return 'A protected foundation for the next generation.'}},academy:{title:'Invest in family education',amount:60000,ok:s=>{s.education+=60000;s.reputation=Math.min(100,s.reputation+2);return 'Future leaders gain the tools to steward capital.'}},give:{title:'Make a community endowment',amount:40000,ok:s=>{s.philanthropy+=40000;s.reputation=Math.min(100,s.reputation+7);return 'Your family invests in a stronger community.'}},council:{title:'Form a family council',amount:90000,ok:s=>{s.reputation=Math.min(100,s.reputation+9);s.education+=15000;return 'A shared purpose and clear governance strengthen the family.'}},reserve:{title:'Build a protected reserve',amount:150000,ok:s=>{s.trust+=150000;s.reputation=Math.min(100,s.reputation+1);return 'Your reserve is protected and earns a steady 4.5%.'}}};const o=options[id];if(!o||state.cash<o.amount){notify('Not enough liquid capital for this move.');return}confirmModal(o.title,`Commit ${money(o.amount)}? This uses your one strategic move for ${state.year}.`,()=>{state.cash-=o.amount;o.ok(state);state.actions=1;state.logs.push({year:state.year,title:o.title,body:`Committed ${money(o.amount)} toward family continuity.`});save();selected=null;notify('Decision recorded in the family book.');render()});}
67: function showDeals(){let choices=[...deals].sort(()=>Math.random()-.5).slice(0,3);let html=`<div class="eyebrow">A GENERATIONAL INVESTMENT</div><h2>Explore the deal book</h2><p>Select one enterprise to acquire. Businesses generate annual income and appreciate over time. You can close the deal only if you have enough liquid capital.</p><div class="portfolio-list">${choices.map(d=>`<div class="asset-row" style="grid-template-columns:1fr auto"><div><strong>${d.icon} &nbsp;${d.name}</strong><div style="font:10px 'DM Sans';color:#7c887f;margin-top:4px">${d.desc}</div><span>${d.kind} · ${d.risk} risk · ${(d.yield*100).toFixed(1)}% yield</span></div><button class="confirm" style="border:0;border-radius:3px;padding:10px;background:${state.cash>=d.cost?'#204e3a':'#a9b0a7'};color:white;font:10px 'DM Mono';white-space:nowrap" onclick="buyDeal('${d.id}')">${money(d.cost)}</button></div>`).join('')}</div><div class="modal-actions"><button onclick="closeModal()">BACK</button></div>`;openModal(html)}
68: function buyDeal(id){let d=deals.find(x=>x.id===id);if(!d||state.cash<d.cost){notify('Not enough liquid capital for this enterprise.');return}state.cash-=d.cost;state.assets.push({id:d.id,name:d.name,kind:d.kind,value:d.cost,yield:d.yield,growth:d.growth,risk:d.risk});state.actions=1;state.logs.push({year:state.year,title:`Acquired ${d.name}`,body:`Invested ${money(d.cost)} in ${d.kind.toLowerCase()} with a ${(d.yield*100).toFixed(1)}% annual yield.`});save();closeModal();selected=null;render();notify(`${d.name} joins your family portfolio.`)}
69: function confirmModal(title,body,action){openModal(`<div class="eyebrow">FAMILY OFFICE DECISION</div><h2>${title}</h2><p>${body}</p><div class="modal-actions"><button onclick="closeModal()">RECONSIDER</button><button class="confirm" id="modalConfirm">CONFIRM MOVE</button></div>`);document.getElementById('modalConfirm').onclick=()=>{closeModal();action()}}
70: function openModal(html){document.getElementById('modal').innerHTML=html;document.getElementById('modalBack').classList.add('show')}
71: function closeModal(){document.getElementById('modalBack').classList.remove('show')}
72: document.getElementById('modalBack').addEventListener('click',e=>{if(e.target.id==='modalBack')closeModal()});
73: function advanceYear(){if(state.ended){resetGame();return}if(state.actions<1){notify('Choose one strategic move before closing the year.');return}let before=wealth();let earned=income();state.cash+=earned;state.cash-=65000;state.assets.forEach(a=>a.value*=1+a.growth);state.trust*=1.045;let event=events[(Math.floor((state.year-2026)/2)+1)%events.length];let effect=event.effect(state);state.history.push({year:state.year,wealth:before});let result=`Annual income ${money(earned)}; operating costs $65,000. ${effect}.`;state.logs.push({year:state.year,title:event.title,body:result});state.year++;state.actions=0;selected=null;if(state.year>=2046||legacyScore()>=100)state.ended=true;save();render();window.scrollTo(0,0);notify(`${event.title} · ${effect}`)}
74: function confirmReset(){confirmModal('Begin a new legacy?',`This will replace your current family record and return to 2026 with ${money(START.cash)} in starting capital.`,resetGame)}
75: function resetGame(){state=structuredClone(START);view='home';selected=null;save();closeModal();render();window.scrollTo(0,0);notify('A new family story begins.')}
76: function notify(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
77: render();
78: </script>
79: </body>
80: </html>

