 :root{--ink:#17231f;--muted:#75817b;--green:#204e3a;--green2:#326b4f;--mint:#dce9dc;--paper:#f6f5ef;--white:#fffefa;--gold:#bd9750;--line:#e6e5dc;--red:#a64e43;--shadow:0 12px 32px #1c2a2010}
