function chooseMove(id){if(state.ended||state.actions>=1)return;selected=id;if(id==='deal'){showDeals();return}if(id==='hold'){state.actions=1;log('Held steady','Chose not to make a new investment; annual operations and historical events still apply.');save();selected=null;notify('No-cost move recorded. You can close the year.');render();return}
 const options={trust:{title:'Establish a family trust',amount:250000,ok:s=>{s.trust+=250000;s.reputation=Math.min(100,s.reputation+2);return 'A protected foundation for the next generation.'}},academy:{title:'Invest in family education',amount:60000,ok:s=>{s.education+=60000;s.family.filter(p=>p.alive&&p.status==='active').forEach(p=>p.traits.education=Math.min(10,p.traits.education+1));s.reputation=Math.min(100,s.reputation+2);return 'Future leaders gain the tools to steward capital.'}},give:{title:'Make a community endowment',amount:40000,ok:s=>{s.philanthropy+=40000;s.reputation=Math.min(100,s.reputation+7);return 'Your family invests in a stronger community.'}},council:{title:'Form a family council',amount:90000,ok:s=>{s.reputation=Math.min(100,s.reputation+9);s.education+=15000;s.family.filter(p=>p.alive&&p.status==='active').forEach(p=>p.traits.loyalty=Math.min(10,p.traits.loyalty+1));return 'A shared purpose and clear governance strengthen the family.'}},reserve:{title:'Build a protected reserve',amount:150000,ok:s=>{s.trust+=150000;s.reputation=Math.min(100,s.reputation+1);return 'Your reserve is protected and earns a steady 4.5%.'}}};let o=options[id];if(!o||state.cash<o.amount){notify('Not enough liquid capital for this move.');return}confirmModal(o.title,`Commit ${money(o.amount)}? This uses your one strategic move for ${state.year}.`,()=>{state.cash-=o.amount;let message=o.ok(state);state.actions=1;log(o.title,`Committed ${money(o.amount)}. ${message}`);save();selected=null;notify('Decision recorded in the family book.');render()})}
function showDeals(){let choices=[...deals].sort(()=>Math.random()-.5).slice(0,3);let html=`<div class="eyebrow">A GENERATIONAL INVESTMENT</div><h2>Explore the deal book</h2><p>Select one enterprise to acquire. Businesses generate annual income and appreciate over time. You can close the deal only if you have enough liquid capital.</p><div class="portfolio-list">${choices.map(d=>`<div class="asset-row" style="grid-template-columns:1fr auto"><div><strong>${d.icon} &nbsp;${d.name}</strong><div style="font:10px 'DM Sans';color:#7c887f;margin-top:4px">${d.desc}</div><span>${d.kind} · ${d.risk} risk · ${(d.yield*100).toFixed(1)}% yield</span></div><button class="confirm" style="border:0;border-radius:3px;padding:10px;background:${state.cash>=d.cost?'#204e3a':'#a9b0a7'};color:white;font:10px 'DM Mono';white-space:nowrap" onclick="buyDeal('${d.id}')">${money(d.cost)}</button></div>`).join('')}</div><div class="modal-actions"><button onclick="closeModal()">BACK</button></div>`;openModal(html)}
function buyDeal(id){let d=deals.find(x=>x.id===id);if(!d||state.cash<d.cost){notify('Not enough liquid capital for this enterprise.');return}state.cash-=d.cost;state.assets.push({id:d.id,name:d.name,kind:d.kind,value:d.cost,yield:d.yield,growth:d.growth,risk:d.risk});state.actions=1;log(`Acquired ${d.name}`,`Invested ${money(d.cost)} in ${d.kind.toLowerCase()} with a ${(d.yield*100).toFixed(1)}% annual yield.`);save();closeModal();selected=null;render();notify(`${d.name} joins your family portfolio.`)}
function confirmModal(title,body,action){openModal(`<div class="eyebrow">FAMILY OFFICE DECISION</div><h2>${title}</h2><p>${body}</p><div class="modal-actions"><button onclick="closeModal()">RECONSIDER</button><button class="confirm" id="modalConfirm">CONFIRM MOVE</button></div>`);document.getElementById('modalConfirm').onclick=()=>{closeModal();action()}}
function openModal(html){document.getElementById('modal').innerHTML=html;document.getElementById('modalBack').classList.add('show')}
function closeModal(){document.getElementById('modalBack').classList.remove('show')}
document.getElementById('modalBack').addEventListener('click',e=>{if(e.target.id==='modalBack')closeModal()});
function addHeirs(parent){let children=state.family.filter(p=>p.parentId===parent.id&&p.alive&&p.status==='active');while(children.length<2){let id='p'+(Math.max(0,...state.family.map(p=>Number(p.id.slice(1))||0))+1),used=new Set(state.family.map(p=>p.name));let name;do{name=names[rand(0,names.length-1)]}while(used.has(name));let child=makePerson(id,name,children.length?7:11,parent.id,'Child');state.family.push(child);children.push(child)}}
function eligibleHeirs(steward){let direct=state.family.filter(p=>p.parentId===steward.id&&p.alive&&p.status==='active'&&p.age>=18);if(direct.length)return direct;return state.family.filter(p=>p.id!==steward.id&&p.alive&&p.status==='active'&&p.age>=18)}
function succeed(){let old=currentSteward(),candidates=eligibleHeirs(old);if(!candidates.length)return '';let heir=candidates.sort((a,b)=>(b.traits.prudence*2+b.traits.education+b.traits.loyalty-b.traits.ambition*.25)-(a.traits.prudence*2+a.traits.education+a.traits.loyalty-a.traits.ambition*.25))[0];state.stewardId=heir.id;state.officeYears=0;heir.relation='Steward';addHeirs(heir);let note=`${heir.name} takes the chair from ${old.name}.`;if(heir.traits.prudence<=3){let loss=Math.max(0,wealth()*(.13+(4-heir.traits.prudence)*.035));state.cash-=Math.min(state.cash,loss);let rest=loss-Math.max(0,Math.min(state.cash+loss,loss));if(rest>0){let factor=Math.max(0,1-rest/Math.max(1,state.trust+state.assets.reduce((n,a)=>n+a.value,0)));state.assets.forEach(a=>a.value*=factor);state.trust*=factor}heir.badChoices++;state.reputation=Math.max(0,state.reputation-5);note+=` ${heir.name}’s reckless spending dissipates ${compact(loss)} of the estate; reputation −5.`}else if(heir.traits.prudence>=7){state.reputation=Math.min(100,state.reputation+2);note+=' A prudent hand steadies the office; reputation +2.'}log('A new generation takes the office',note);return note}
function familyYear(){let notes=[];state.family.forEach(p=>{if(!p.alive)return;p.age++;if(p.age>88&&Math.random()<.12){p.alive=false;p.status='deceased';notes.push(`${p.name} passed away at age ${p.age}.`)}});let steward=currentSteward();if(steward&&steward.alive&&steward.status==='active'&&steward.traits.prudence<=3&&Math.random()<.035){let loss=wealth()*.06;state.cash-=Math.min(Math.max(0,state.cash),loss);let remaining=loss-Math.max(0,Math.min(Math.max(0,state.cash)+loss,loss));if(remaining>0){let base=state.trust+state.assets.reduce((n,a)=>n+a.value,0),factor=Math.max(0,1-remaining/Math.max(1,base));state.assets.forEach(a=>a.value*=factor);state.trust*=factor}steward.badChoices++;state.reputation=Math.max(0,state.reputation-2);notes.push(`${steward.name} made a reckless personal investment, costing the estate about ${compact(loss)}.`)}
 state.family.forEach(p=>{if(!p.alive||p.status!=='active'||p.id===state.stewardId||p.age<18)return;if(p.traits.prudence<=3&&p.badChoices===0&&Math.random()<.025){p.badChoices++;notes.push(`${p.name} made a costly personal choice.`)}let poorProspects=wealth()/Math.max(1,activeFamily().length)<85000;if((poorProspects||p.badChoices>=2)&&p.traits.loyalty<=4&&Math.random()<.28){p.status='away';notes.push(`${p.name} left the family office for better prospects elsewhere.`)}});
 if(state.family.filter(p=>p.alive&&p.status==='active').length===0){let living=state.family.filter(p=>p.alive);if(living.length)living[0].status='active'}return notes}
function squander(loss){let available=Math.max(0,wealth());loss=Math.min(available,loss);let remain=loss,fromCash=Math.min(Math.max(0,state.cash),remain);state.cash-=fromCash;remain-=fromCash;let base=state.trust+state.assets.reduce((n,a)=>n+a.value,0);if(remain>0&&base>0){let f=Math.max(0,1-remain/base);state.assets.forEach(a=>a.value*=f);state.trust*=f}return loss}
function advanceYear(){if(state.ended){resetGame();return}if(state.actions<1){notify('Choose one strategic move before closing the year.');return}let before=wealth(),earned=income();state.cash+=earned;let annualCost=65000+activeFamily().length*3500;state.cash-=annualCost;state.assets.forEach(a=>a.value=Math.max(0,a.value*(1+a.growth)));state.trust=Math.max(0,state.trust*1.045);let event=forecast(),effect=event.effect(state),familyNotes=familyYear();state.history.push({year:state.year,wealth:before});let yearText=`Annual income ${money(earned)}; family and office costs ${money(annualCost)}. ${effect}.`;if(familyNotes.length)yearText+=' '+familyNotes.join(' ');if(historicFor(state.year)){state.appliedEvents.push(state.year);log(event.title,yearText)}else if(familyNotes.length)log('Family affairs',yearText);state.year++;state.actions=0;selected=null;state.officeYears++;
 let steward=currentSteward(),handover='';if(!steward||!steward.alive||steward.status!=='active'||state.officeYears>=20)handover=succeed();if(!handover&&state.officeYears>=20)state.officeYears=0;if(handover)yearText+=' '+handover;if(state.year>=state.startYear+RUN_LENGTH){state.ended=true;log('Three centuries complete',`The 300-year family challenge ends with an estate of ${compact(wealth())}.`)}else if(wealth()<=0||state.cash<-250000){state.ended=true;log('The family office becomes insolvent',`After ${state.year-state.startYear} years, debt and depleted reserves end the family’s control of the office.`)}else if(!state.family.some(p=>p.alive&&p.status==='active')){state.ended=true;log('The family office closes','No active family members remain to carry the office forward.')}save();render();window.scrollTo(0,0);notify(`${event.title} · ${effect}`)}
function confirmReset(){confirmModal('Begin a new legacy?','This will replace the current family record and return to the founding-year selection.',resetGame)}
function resetGame(){state=structuredClone(START);view='home';selected=null;save();closeModal();render();window.scrollTo(0,0);notify('Choose a year for your new family story.')}
function notify(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
render();
</script>

