<body>
<div id="app"><div class="shell"><header class="topbar"><div class="brand"><div class="brand-mark">E</div><div><div class="brand-name">EVERGREEN</div><div class="brand-sub">A LEGACY BUILDER</div></div></div><div class="top-right"><span>PRIVATE FAMILY OFFICE</span><button class="reset-btn" aria-label="New game" title="Start a new legacy" onclick="confirmReset()">↻</button></div></header><main class="main"><section class="card setup"><div class="eyebrow">A 300-YEAR FAMILY CHALLENGE</div><h1>Build beyond your own lifetime.</h1><p>Guide a family office through three centuries of American history. Choose your founding year, prepare successors, and try to preserve your family’s wealth and purpose for 300 years.</p><div class="family-info"><span>HISTORICAL EVENTS</span><span>GENERATIONAL SUCCESSION</span><span>FAMILY TREE</span></div><label for="startYear">CHOOSE YOUR FOUNDING YEAR</label><input id="startYear" type="range" min="1776" max="2026" value="2026" oninput="document.getElementById('startYearValue').textContent=this.value"><div class="setup-year"><span>1776</span><strong id="startYearValue">2026</strong><span>2026</span></div><button class="primary-btn" onclick="startGame(document.getElementById('startYear').value)">OPEN THE FAMILY OFFICE →</button><p style="font-size:10px;margin-top:18px">A new game can begin in any year from 1776 through 2026. Historical events occur in their actual year; the game continues into a fictional future if needed.</p></section></main><footer class="footer"><span>EVERGREEN FAMILY OFFICE SIMULATOR</span><span>FICTIONAL SCENARIO · HISTORIC EVENTS ARE SIMPLIFIED</span></footer></div></div>
<div class="toast" id="toast"></div>
<div class="modal-back" id="modalBack"><div class="modal" id="modal"></div></div>
<script>

const THIS_YEAR=2026, RUN_LENGTH=300;
const START={year:THIS_YEAR,startYear:THIS_YEAR,cash:1250000,assets:[],trust:0,education:0,philanthropy:0,reputation:34,actions:0,history:[],logs:[],ended:false,started:false,family:[],stewardId:null,officeYears:0,appliedEvents:[]};
const deals=[
 {id:'rail',name:'Regional Rail',icon:'↗',kind:'Infrastructure',cost:420000,yield:.095,growth:.035,desc:'A vital freight corridor with steady contracts.',risk:'Low'},
 {id:'mill',name:'Timber & Paper Mill',icon:'⌂',kind:'Industry',cost:310000,yield:.12,growth:.025,desc:'Acquire a profitable local mill and its workforce.',risk:'Medium'},
 {id:'land',name:'Riverfront Acreage',icon:'⌁',kind:'Real estate',cost:260000,yield:.035,growth:.105,desc:'Patiently hold land on the edge of a growing city.',risk:'Medium'},
 {id:'utility',name:'City Electric Works',icon:'ϟ',kind:'Utilities',cost:510000,yield:.075,growth:.06,desc:'Power a growing city through a regulated utility.',risk:'Low'},
 {id:'fund',name:'Diversified Holdings',icon:'◉',kind:'Public markets',cost:180000,yield:.055,growth:.075,desc:'A broad basket of established enterprises.',risk:'Balanced'}
];
const historyEvents=[
 {year:1776,title:'A nation founded in uncertainty',body:'The Declaration of Independence begins a long experiment in self-government. War disrupts commerce, but patient suppliers and landholders may benefit.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Infrastructure'?1.08:.92);s.cash-=Math.min(s.cash,30000);return 'War disrupted trade; infrastructure holdings +8%, other assets −8%, reserves −$30,000';}},
 {year:1783,title:'Peace and a fragile republic',body:'The Revolutionary War ends. Trade resumes slowly as the new nation builds its institutions.',effect:s=>{s.reputation=Math.min(100,s.reputation+2);s.cash+=25000;return 'Peace restored trade; +$25,000 and +2 reputation';}},
 {year:1787,title:'A new constitution',body:'A stronger federal framework improves confidence in commerce and long-term contracts.',effect:s=>{s.assets.forEach(a=>a.value*=1.05);return 'Confidence lifts portfolio values by 5%';}},
 {year:1803,title:'The Louisiana Purchase',body:'The nation doubles in size. Land and transport routes across the interior gain strategic value.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Real estate'||a.kind==='Infrastructure'?1.16:1.02);return 'Land and infrastructure +16%; other holdings +2%';}},
 {year:1812,title:'War of 1812',body:'Blockades and conflict interrupt trade. Liquid reserves cushion the family against a sharp contraction.',effect:s=>{s.assets.forEach(a=>a.value*=.88);s.cash-=Math.min(s.cash,50000);return 'Portfolio −12%; reserves −$50,000';}},
 {year:1848,title:'Gold rush and westward growth',body:'The California Gold Rush accelerates migration, settlement, and demand for transport and supplies.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Infrastructure'||a.kind==='Real estate'?1.18:1.06);return 'Infrastructure and land +18%; other assets +6%';}},
 {year:1861,title:'Civil War begins',body:'Civil conflict fractures markets and communities. Holdings are exposed to severe uncertainty.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Industry'?.78:.84);s.reputation=Math.max(0,s.reputation-3);return 'Portfolio −16% (industry −22%); reputation −3';}},
 {year:1865,title:'Reconstruction',body:'The war ends. Recovery is uneven, while new infrastructure and industrial demand reshape the economy.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Infrastructure'||a.kind==='Industry'?1.14:1.06);return 'Infrastructure and industry +14%; other assets +6%';}},
 {year:1873,title:'Panic of 1873',body:'A financial panic triggers a prolonged downturn. Overextended businesses and concentrated fortunes are vulnerable.',effect:s=>{s.assets.forEach(a=>a.value*=.78);s.cash-=Math.min(s.cash,25000);return 'Portfolio −22%; emergency costs −$25,000';}},
 {year:1893,title:'A severe depression',body:'Bank failures and unemployment spread through the country. Diversified reserves help the family endure.',effect:s=>{s.assets.forEach(a=>a.value*=.8);s.trust*=.96;return 'Assets −20%; trust −4%';}},
 {year:1907,title:'The Panic of 1907',body:'A banking crisis freezes credit. Income-producing assets remain valuable, but liquidity is prized.',effect:s=>{s.assets.forEach(a=>a.value*=.86);s.cash-=Math.min(s.cash,Math.max(0,50000-s.trust*.02));return 'Portfolio −14%; liquidity support costs up to $50,000';}},
 {year:1917,title:'America enters the Great War',body:'Mobilization increases demand for infrastructure and industry, alongside family service and sacrifice.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Industry'||a.kind==='Infrastructure'?1.12:1.03);s.reputation=Math.min(100,s.reputation+1);return 'Industry and infrastructure +12%; other holdings +3%';}},
 {year:1929,title:'The market crash',body:'The stock market collapses and a deep economic crisis follows. Concentrated and leveraged fortunes face ruin.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Public markets'?.55:.72);s.cash-=Math.min(s.cash,40000);return 'Public markets −45%, other assets −28%; costs −$40,000';}},
 {year:1933,title:'The New Deal',body:'Public works and financial reforms begin reshaping the economy. Long-term infrastructure benefits from investment.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Infrastructure'?1.12:1.04);s.reputation=Math.min(100,s.reputation+2);return 'Infrastructure +12%, other assets +4%; reputation +2';}},
 {year:1941,title:'The United States enters World War II',body:'Wartime production transforms industry and daily life. Families face uncertainty as the nation mobilizes.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Industry'||a.kind==='Infrastructure'?1.1:1.02);s.education+=5000;return 'Industry and infrastructure +10%; family service fund −$5,000';}},
 {year:1945,title:'A postwar boom begins',body:'Demobilization gives way to expanding suburbs, consumer markets, and a long period of growth.',effect:s=>{s.assets.forEach(a=>a.value*=1.12);return 'Portfolio values +12%';}},
 {year:1973,title:'Oil shock and stagflation',body:'Energy shortages and inflation strain businesses and household budgets.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Real estate'?1.02:.82);s.cash-=Math.min(s.cash,30000);return 'Most assets −18%, land +2%; costs −$30,000';}},
 {year:1987,title:'Black Monday',body:'Global markets plunge in a single day, testing investors’ resolve.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Public markets'?.78:.94);return 'Public markets −22%; other assets −6%';}},
 {year:2001,title:'A changed America',body:'The September 11 attacks bring loss, uncertainty, and disruption to travel and commerce.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Infrastructure'?.9:.95);s.reputation=Math.min(100,s.reputation+1);return 'Infrastructure −10%, other holdings −5%; +1 community reputation';}},
 {year:2008,title:'Global financial crisis',body:'A housing collapse and credit crisis damage markets worldwide. Diversification and patient stewardship matter.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Real estate'?.68:a.kind==='Public markets'?.72:.84);s.trust*=.97;return 'Land −32%, public markets −28%, other assets −16%; trust −3%';}},
 {year:2020,title:'A pandemic reshapes daily life',body:'A public-health emergency interrupts commerce and brings profound family and community strain.',effect:s=>{s.assets.forEach(a=>a.value*=a.kind==='Infrastructure'?.8:.88);s.reputation=Math.max(0,s.reputation-1);return 'Infrastructure −20%, other assets −12%; reputation −1';}}
];
const names=['Alex Morgan','Eleanor Morgan','James Morgan','Clara Morgan','Thomas Morgan','Margaret Morgan','Edwin Morgan','Louisa Morgan','Henry Morgan','Ada Morgan','Samuel Morgan','Josephine Morgan','Arthur Morgan','Grace Morgan','Frederick Morgan','Elizabeth Morgan','Walter Morgan','Helen Morgan','Charles Morgan','Amelia Morgan'];
let state=load(),view='home',selected=null,toastTimer;
function makePerson(id,name,age,parentId,relation,traits={}){return {id,name,age,parentId,relation,alive:true,status:'active',traits:{prudence:traits.prudence||rand(3,9),ambition:traits.ambition||rand(3,9),education:traits.education||rand(2,8),loyalty:traits.loyalty||rand(3,9)},badChoices:0};}
function rand(min,max){return Math.floor(Math.random()*(max-min+1))+min}
function seedFamily(s){let founder=makePerson('p1',names[rand(0,1)],42,null,'Founder',{prudence:6,ambition:6,education:5,loyalty:8});let spouse=makePerson('p2',names[rand(2,3)],40,'p1','Spouse');let kids=[makePerson('p3',names[4],17,'p1','Child',{prudence:7,ambition:6,education:5,loyalty:8}),makePerson('p4',names[5],14,'p1','Child',{prudence:5,ambition:7,education:6,loyalty:6}),makePerson('p5',names[6],10,'p1','Child',{prudence:4,ambition:8,education:3,loyalty:5})];s.family=[founder,spouse,...kids];s.stewardId='p1';s.officeYears=0;}
function load(){try{let x=JSON.parse(localStorage.getItem('evergreen-save'));if(!x)return structuredClone(START);let s={...structuredClone(START),...x};if(s.started===undefined)s.started=true;if(!s.startYear)s.startYear=s.year||THIS_YEAR;if(!Array.isArray(s.family)||!s.family.length)seedFamily(s);if(!s.stewardId)s.stewardId=s.family[0]?.id||'p1';if(!Array.isArray(s.appliedEvents))s.appliedEvents=[];if(s.startYear<1776||s.startYear>THIS_YEAR)s.startYear=THIS_YEAR;return s}catch{return structuredClone(START)}}
function save(){localStorage.setItem('evergreen-save',JSON.stringify(state))}
const money=n=>'$'+Math.round(n).toLocaleString('en-US'),compact=n=>Math.abs(n)>=1e6?'$'+(n/1e6).toFixed(2)+'m':Math.abs(n)>=1000?'$'+Math.round(n/1000)+'k':money(n);
function wealth(){return state.cash+state.trust+state.assets.reduce((n,a)=>n+a.value,0)}function income(){return state.assets.reduce((n,a)=>n+a.value*a.yield,0)+state.trust*.045}
function currentSteward(){return state.family.find(p=>p.id===state.stewardId)}function activeFamily(){return state.family.filter(p=>p.alive&&p.status==='active')}
function legacyScore(){return Math.round(Math.min(100,(wealth()/10000000)*30+state.reputation*.2+Math.min(state.education/10000,10)*.8+Math.min(state.philanthropy/50000,10)*.8+state.assets.length*2+Math.min(20,activeFamily().length)*.5))}
function fmtYear(){return `${state.year} / ${state.startYear+RUN_LENGTH}`}
function log(title,body){state.logs.push({year:state.year,title,body})}
function historicFor(year){return historyEvents.find(e=>e.year===year)}
function forecast(){let h=historicFor(state.year);if(h)return h;return {title:state.year>THIS_YEAR&&state.year%10===0?'A new technological age':'A year of stewardship',body:state.year>THIS_YEAR&&state.year%10===0?'A future wave of invention and civic change creates fresh opportunities and risks.':'Your family’s long-term choices matter more than any single season.',effect:s=>{if(s.year>THIS_YEAR&&s.year%10===0){s.assets.forEach(a=>a.value*=a.kind==='Infrastructure'||a.kind==='Utilities'?1.08:1.03);return 'Future growth lifts infrastructure and utilities +8%; other holdings +3%'}return 'No exceptional market shock this year'}}}
function startGame(year){let s=structuredClone(START);s.started=true;s.startYear=Number(year);s.year=Number(year);seedFamily(s);state=s;view='home';save();render();notify(`The family record opens in ${year}.`)}
function setView(next){view=next;render();window.scrollTo(0,0)}
function svgChart(){let vals=state.history.map(x=>x.wealth);vals.push(wealth());if(vals.length<2)vals=[wealth()*.94,wealth()];let min=Math.min(...vals)*.94,max=Math.max(...vals)*1.02,range=max-min||1;let pts=vals.map((v,i)=>`${i/(vals.length-1)*100},${72-(v-min)/range*60}`).join(' ');return `<svg viewBox="0 0 100 80" preserveAspectRatio="none" aria-label="Wealth over time"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#6c9878" stop-opacity=".24"/><stop offset="1" stop-color="#6c9878" stop-opacity="0"/></linearGradient></defs><polygon points="0,80 ${pts} 100,80" fill="url(#fill)"/><polyline points="${pts}" fill="none" stroke="#326b4f" stroke-width="1.7" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/><circle cx="100" cy="${72-(vals[vals.length-1]-min)/range*60}" r="2.3" fill="#326b4f" vector-effect="non-scaling-stroke"/></svg>`}
function moveCard(id,icon,name,desc,cost,label,disabled=false){return `<article class="move-card card ${disabled?'locked':''} ${selected===id?'selected':''}" data-move="${id}"><div class="move-icon">${icon}</div><div class="move-name">${name}</div><div class="move-desc">${desc}</div><div class="move-bottom"><span class="move-price">${label||cost}</span><span class="move-arrow">↗</span></div></article>`}
function render(){
 const header=`<header class="topbar"><div class="brand"><div class="brand-mark">E</div><div><div class="brand-name">EVERGREEN</div><div class="brand-sub">A LEGACY BUILDER</div></div></div><div class="top-right"><span>PRIVATE FAMILY OFFICE</span><button class="reset-btn" aria-label="New game" title="Start a new legacy" onclick="confirmReset()">↻</button></div></header>`;
 let content;
 if(!state.started){content=`<section class="card setup"><div class="eyebrow">A 300-YEAR FAMILY CHALLENGE</div><h1>Build beyond your own lifetime.</h1><p>Guide a family office through three centuries of American history. Choose your founding year, prepare successors, and try to preserve your family’s wealth and purpose for 300 years.</p><div class="family-info"><span>HISTORICAL EVENTS</span><span>GENERATIONAL SUCCESSION</span><span>FAMILY TREE</span></div><label for="startYear">CHOOSE YOUR FOUNDING YEAR</label><input id="startYear" type="range" min="1776" max="${THIS_YEAR}" value="${THIS_YEAR}" oninput="document.getElementById('startYearValue').textContent=this.value"><div class="setup-year"><span>1776</span><strong id="startYearValue">${THIS_YEAR}</strong><span>${THIS_YEAR}</span></div><button class="primary-btn" onclick="startGame(document.getElementById('startYear').value)">OPEN THE FAMILY OFFICE →</button><p style="font-size:10px;margin-top:18px">A new game can begin in any year from 1776 through ${THIS_YEAR}. Historical events occur in their actual year; the game continues into a fictional future if needed.</p></section>`;}
 else {let event=forecast(),canAct=state.actions<1&&!state.ended,earnings=income(),wealthNum=wealth(),score=legacyScore(),steward=currentSteward(),remaining=Math.max(0,state.startYear+RUN_LENGTH-state.year);let hero=`<section class="hero"><div class="hero-copy"><div class="eyebrow">A family enterprise · ${fmtYear()}</div><h1>Build beyond<br>your own lifetime.</h1><p>Grow enduring businesses, steward capital wisely, and prepare the next generation to carry your name forward.</p><div class="hero-meta"><span><i class="dot"></i>${steward?steward.name:'Family'} · Generation ${Math.floor(state.officeYears/20)+1}</span><span>◷ &nbsp;${Math.max(0,20-state.officeYears)} YEARS TO SUCCESSION</span></div></div></section>`;
 let overview=`<div class="overview"><div class="left-col"><section class="card wealth-card"><div class="section-head"><div class="section-title">Family wealth</div><div class="mono">TOTAL ESTATE</div></div><div class="wealth-total"><strong>${compact(wealthNum)}</strong><span class="change">${state.history.length?((wealthNum/state.history[0].wealth-1)*100).toFixed(1):'0.0'}%</span></div><div class="chart-wrap">${svgChart()}</div><div class="chart-labels"><span>FOUNDING YEAR · ${state.startYear}</span><span>NOW · ${state.year}</span></div><div class="stats"><div class="stat"><label>Liquid capital</label><b>${compact(state.cash)}</b><small>Available to deploy</small></div><div class="stat"><label>Annual income</label><b>${compact(earnings)}</b><small>From productive assets</small></div><div class="stat"><label>Holdings</label><b>${state.assets.length+(state.trust>0?1:0)}</b><small>Across ${new Set(state.assets.map(a=>a.kind)).size} sectors</small></div></div></section></div><div class="right-col"><section class="card score-card"><div class="section-head"><div class="section-title">Legacy index</div><div class="mono">OUT OF 100</div></div><div class="score-number">${score}<span style="font:12px 'DM Sans';color:#7b887b"> / 100</span></div><div class="score-sub">${score<35?'A foundation taking shape':score<65?'A respected family institution':score<85?'A lasting dynasty':'An extraordinary legacy'}</div><div class="progress"><i style="width:${score}%"></i></div><div class="score-foot"><span>300-YEAR CHALLENGE</span><span>${remaining} YEARS LEFT</span></div></section><section class="card yield-card"><div class="section-head"><div class="section-title">Capital mix</div><div class="mono">PORTFOLIO</div></div><div class="yield-main"><div class="yield-value">${compact(state.assets.reduce((n,a)=>n+a.value,0)+state.trust)}</div><div class="yield-note">${state.assets.length} ACTIVE HOLDINGS</div></div><div class="yield-bar"><span></span><span></span><span></span></div><div class="legend"><span>Liquid ${compact(state.cash)}</span><span>Trust ${compact(state.trust)}</span></div></section></div></div>`;
 let moves=`<div class="section-row"><div><h2>Make your move</h2><p>One defining decision each year. Choose with care.</p></div><span class="move-count">${state.ended?'LEGACY COMPLETE':canAct?'1 MOVE AVAILABLE':'MOVE MADE'}</span></div><div class="moves">${moveCard('deal','⌂','Acquire an enterprise','Buy a durable business or long-term holding.','','EXPLORE DEALS',!canAct)}${moveCard('trust','◈','Create a family trust','Set aside capital for continuity and stewardship.',money(250000),'SECURE THE FUTURE',!canAct||state.cash<250000)}${moveCard('academy','✦','Educate the next generation','Invest in a capable, principled family council.',money(60000),'INVEST IN PEOPLE',!canAct||state.cash<60000)}${moveCard('give','♡','Give with intention','Support a lasting community institution.',money(40000),'BUILD GOODWILL',!canAct||state.cash<40000)}${moveCard('council','♧','Form a family council','Strengthen governance and improve your reputation.',money(90000),'SET A COMMON PURPOSE',!canAct||state.cash<90000)}${moveCard('reserve','⌁','Protect the reserve','Build resilience; add a modest guaranteed return.',money(150000),'LOW-RISK 4.5% YIELD',!canAct||state.cash<150000)}${moveCard('hold','—','Hold steady','Skip investing this year and advance with no upfront cost.','$0','NO-COST ADVANCE',!canAct)}</div>`;
 let bottom=`<div class="bottom-grid"><section class="card event-card"><div class="event-icon">✧</div><div><div class="event-tag">${historicFor(state.year)?'THIS YEAR IN AMERICA':'IN THIS SEASON'}</div><div class="event-title">${event.title}</div><p class="event-body">${event.body}</p></div></section><section class="card action-card"><div><div class="action-title">${state.ended?'Your story is written':`Year ${state.year} decision`}</div><div class="action-hint">${state.ended?'Three centuries have passed.':canAct?'Choose a move, then close the books.':'Your move is set. Ready to advance?'}</div></div><button class="advance" onclick="advanceYear()" ${(state.actions<1&&!state.ended)?'disabled':''}>${state.ended?'NEW LEGACY':'CLOSE THE YEAR →'}</button></section></div>`;
 let ending=state.ended?`<section class="ending"><div class="eyebrow">THE FAMILY RECORD · ${state.year}</div><h2>${wealthNum>=10000000?'A legacy that endures.':wealthNum>0?'The name survives; the fortune has changed.':'A family fortune lost to time.'}</h2><p>Across 300 years, your family stewarded ${compact(wealthNum)}, built ${state.assets.length} lasting enterprises, and finished with a Legacy Index of ${score}. ${activeFamily().length} family members remain in the office.</p></section>`:'';
 content=view==='home'?`${hero}${ending}${overview}${moves}${bottom}`:view==='portfolio'?portfolioView():view==='family'?familyView():ledgerView();
 }
 document.getElementById('app').innerHTML=`<div class="shell">${header}<main class="main">${content}</main><footer class="footer"><span>EVERGREEN FAMILY OFFICE SIMULATOR</span><span>FICTIONAL SCENARIO · HISTORIC EVENTS ARE SIMPLIFIED</span></footer>${state.started?`<nav class="tabs"><button class="tab ${view==='home'?'active':''}" onclick="setView('home')"><span class="tab-icon">⌂</span>HOME</button><button class="tab ${view==='portfolio'?'active':''}" onclick="setView('portfolio')"><span class="tab-icon">◫</span>PORTFOLIO</button><button class="tab ${view==='family'?'active':''}" onclick="setView('family')"><span class="tab-icon">♧</span>FAMILY</button><button class="tab ${view==='ledger'?'active':''}" onclick="setView('ledger')"><span class="tab-icon">≡</span>BOOK</button></nav>`:''}</div>`;
 document.querySelectorAll('[data-move]').forEach(el=>el.addEventListener('click',()=>chooseMove(el.dataset.move)));
}
function portfolioView(){let total=state.assets.reduce((n,a)=>n+a.value,0);return `<div class="section-row" style="margin-top:5px"><div><h2>Family portfolio</h2><p>Capital at work, built one generation at a time.</p></div><span class="move-count">${state.assets.length} HOLDINGS</span></div><section class="card wealth-card"><div class="section-head"><div class="section-title">Productive assets</div><div class="mono">${compact(total)} TOTAL VALUE</div></div>${state.assets.length?`<div class="portfolio-list">${state.assets.map(a=>`<div class="asset-row"><strong>${a.name}<br><span style="font:9px 'DM Sans';color:#88938a">${a.kind} · ${a.risk} risk</span></strong><span>${compact(a.value)}<br>value</span><span>${compact(a.value*a.yield)}<br>annual income</span></div>`).join('')}</div>`:`<div class="empty">Your family’s first enterprise is waiting to be acquired.<br>Choose “Explore deals” on the home screen to begin.</div>`}<div class="asset-row" style="border-bottom:1px solid var(--line);margin-top:4px"><strong>Family trust</strong><span>${compact(state.trust)}<br>protected</span><span>${compact(state.trust*.045)}<br>annual income</span></div></section><section class="card wealth-card" style="margin-top:14px"><div class="section-head"><div class="section-title">Stewardship & people</div><div class="mono">NON-FINANCIAL CAPITAL</div></div><div class="stats"><div class="stat"><label>Reputation</label><b>${state.reputation} / 100</b><small>Community standing</small></div><div class="stat"><label>Education</label><b>${compact(state.education)}</b><small>Next-gen investment</small></div><div class="stat"><label>Philanthropy</label><b>${compact(state.philanthropy)}</b><small>Giving to date</small></div></div></section>`}
function familyView(){let steward=currentSteward(),active=activeFamily(),maxGen=Math.max(0,...state.family.map(p=>generationOf(p)));let cards=state.family.slice().sort((a,b)=>generationOf(a)-generationOf(b)||b.age-a.age).map(p=>{let parent=state.family.find(x=>x.id===p.parentId),t=p.traits,role=p.id===state.stewardId?'OFFICE STEWARD':p.status==='away'?'LEFT THE FAMILY':p.alive?'FAMILY MEMBER':'DECEASED';return `<article class="person"><div class="person-top"><div><div class="person-name">${p.name}</div><div class="person-meta">${p.relation} · Age ${p.age}${parent?` · child of ${parent.name.split(' ')[0]}`:''}</div></div><span class="badge ${p.status==='away'?'away':''}">${role}</span></div><div class="traits">${trait('Prudence',t.prudence)}${trait('Ambition',t.ambition)}${trait('Education',t.education)}${trait('Loyalty',t.loyalty)}</div>${p.badChoices?`<div class="person-meta">${p.badChoices} recorded poor ${p.badChoices===1?'choice':'choices'}</div>`:''}</article>`}).join('');return `<div class="section-row" style="margin-top:5px"><div><h2>Family tree</h2><p>Attributes shape succession, stewardship, and who stays with the family.</p></div><span class="move-count">${active.length} ACTIVE · GEN ${maxGen+1}</span></div><section class="card wealth-card"><div class="section-head"><div class="section-title">The family office</div><div class="mono">SUCCESSION EVERY ~20 YEARS</div></div><div class="family-info"><span>CURRENT STEWARD · ${steward?steward.name.toUpperCase():'NONE'}</span><span>IN OFFICE · ${state.officeYears} YEARS</span><span>${Math.max(0,20-state.officeYears)} TO HANDOVER</span></div><p style="font-size:11px;color:var(--muted);line-height:1.55">Successors are chosen from active adult descendants. Prudence and education improve their stewardship; a reckless heir may dissipate the estate. Members with poor prospects or repeated bad choices can leave for a life outside the family office.</p></section><div class="family-grid">${cards}</div>`}
function trait(label,value){return `<div class="trait"><span>${label}</span><b>${value}/10</b><div class="trait-bar"><i style="width:${value*10}%"></i></div></div>`}
function generationOf(person){let depth=0,p=person,seen=new Set();while(p.parentId&&!seen.has(p.id)){seen.add(p.id);p=state.family.find(x=>x.id===p.parentId);if(!p)break;depth++;}return depth}
function ledgerView(){return `<div class="section-row" style="margin-top:5px"><div><h2>Family book</h2><p>A record of decisions, history, and the values behind them.</p></div><span class="move-count">${state.logs.length} ENTRIES</span></div><section class="card wealth-card"><div class="section-head"><div class="section-title">Family chronicle</div><div class="mono">${state.year} · ${state.logs.length} YEARS</div></div><div class="timeline">${state.logs.length?state.logs.slice().reverse().map(l=>`<div class="timeline-item"><strong>${l.year} · ${l.title}</strong><p>${l.body}</p></div>`).join(''):`<div class="empty-state">The family book is open. Your first annual decision will begin the story.</div>`}</div></section>`}

function chooseMove(id){if(state.ended||state.actions>=1)return;selected=id;if(id==='deal'){showDeals();return}if(id==='hold'){state.actions=1;log('Held steady','Chose not to make a new investment; annual operations and historical events still apply.');save();selected=null;notify('No-cost move recorded. You can close the year.');render();return}
 const options={trust:{title:'Establish a family trust',amount:250000,ok:s=>{s.trust+=250000;s.reputation=Math.min(100,s.reputation+2);return 'A protected foundation for the next generation.'}},academy:{title:'Invest in family education',amount:60000,ok:s=>{s.education+=60000;s.family.filter(p=>p.alive&&p.status==='active').forEach(p=>p.traits.education=Math.min(10,p.traits.education+1));s.reputation=Math.min(100,s.reputation+2);return 'Future leaders gain the tools to steward capital.'}},give:{title:'Make a community endowment',amount:40000,ok:s=>{s.philanthropy+=40000;s.reputation=Math.min(100,s.reputation+7);return 'Your family invests in a stronger community.'}},council:{title:'Form a family council',amount:90000,ok:s=>{s.reputation=Math.min(100,s.reputation+9);s.education+=15000;s.family.filter(p=>p.alive&&p.status==='active').forEach(p=>p.traits.loyalty=Math.min(10,p.traits.loyalty+1));return 'A shared purpose and clear governance strengthen the family.'}},reserve:{title:'Build a protected reserve',amount:150000,ok:s=>{s.trust+=150000;s.reputation=Math.min(100,s.reputation+1);return 'Your reserve is protected and earns a steady 4.5%.'}}};let o=options[id];if(!o||state.cash<o.amount){notify('Not enough liquid capital for this move.');return}confirmModal(o.title,`Commit ${money(o.amount)}? This uses your one strategic move for ${state.year}.`,()=>{state.cash-=o.amount;let message=o.ok(state);state.actions=1;log(o.title,`Committed ${money(o.amount)}. ${message}`);save();selected=null;notify('Decision recorded in the family book.');render()})}
function showDeals(){let choices=[...deals].sort(()=>Math.random()-.5).slice(0,3);let html=`<div class="eyebrow">A GENERATIONAL INVESTMENT</div><h2>Explore the deal book</h2><p>Select one enterprise to acquire. Businesses generate annual income and appreciate over time. You can close the deal only if you have enough liquid capital.</p><div class="portfolio-list">${choices.map(d=>`<div class="asset-row" style="grid-template-columns:1fr auto"><div><strong>${d.icon} &nbsp;${d.name}</strong><div style="font:10px 'DM Sans';color:#7c887f;margin-top:4px">${d.desc}</div><span>${d.kind} · ${d.risk} risk · ${(d.yield*100).toFixed(1)}% yield</span></div><button class="confirm" style="border:0;border-radius:3px;padding:10px;background:${state.cash>=d.cost?'#204e3a':'#a9b0a7'};color:white;font:10px 'DM Mono';white-space:nowrap" onclick="buyDeal('${d.id}')">${money(d.cost)}</button></div>`).join('')}</div><div class="modal-actions"><button onclick="closeModal()">BACK</button></div>`;openModal(html)}
function buyDeal(id){let d=deals.find(x=>x.id===id);if(!d||state.cash<d.cost){notify('Not enough liquid capital for this enterprise.');return}state.cash-=d.cost;state.assets.push({id:d.id,name:d.name,kind:d.kind,value:d.cost,yield:d.yield,growth:d.growth,risk:d.risk});state.actions=1;log(`Acquired ${d.name}`,`Invested ${money(d.cost)} in ${d.kind.toLowerCase()} with a ${(d.yield*100).toFixed(1)}% annual yield.`);save();closeModal();selected=null;render();notify(`${d.name} joins your family portfolio.`)}
function confirmModal(title,body,action){openModal(`<div class="eyebrow">FAMILY OFFICE DECISION</div><h2>${title}</h2><p>${body}</p><div class="modal-actions"><button onclick="closeModal()">RECONSIDER</button><button class="confirm" id="modalConfirm">CONFIRM MOVE</button></div>`);document.getElementById('modalConfirm').onclick=()=>{closeModal();action()}}
function openModal(html){document.getElementById('modal').innerHTML=html;document.getElementById('modalBack').classList.add('show')}
function closeModal(){document.getElementById('modalBack').classList.remove('show')}
document.getElementById('modalBack').addEventListener('click',e=>{if(e.target.id==='modalBack')closeModal()});
function addHeirs(parent){let children=state.family.filter(p=>p.parentId===parent.id&&p.alive&&p.status==='active');while(children.length<2){let id='p'+(Math.max(0,...state.family.map(p=>Number(p.id.slice(1))||0))+1),used=new Set(state.family.map(p=>p.name)),baseName=names[rand(0,names.length-1)],name=baseName,suffix=2;while(used.has(name))name=`${baseName} ${suffix++}`;let child=makePerson(id,name,children.length?7:11,parent.id,'Child');state.family.push(child);children.push(child)}}
